document.querySelector("#telegramClear").onclick=async()=>{try{const r=await api("/api/ai/manager/telegram/clear",{method:"POST"});const d=await r.json();showState(r.ok?(isEn?"Managed Telegram destination cleared.":"تم مسح وجهة Telegram المحفوظة."):d.error||d.status);}catch(e){showState(String(e.message||e))}};
document.querySelector("#telegramWebhook").onclick=async()=>{if(!confirm(isEn?"Remove the Telegram webhook?":"هل تريد إزالة Telegram Webhook؟"))return;try{const r=await api("/api/ai/manager/telegram/delete-webhook",{method:"POST"});const d=await r.json();showState(r.ok?(isEn?"Webhook removed.":"تمت إزالة Webhook."):d.error||d.status);telegramStatus();}catch(e){showState(String(e.message||e))}};
document.querySelector("#telegramTest").onclick=async()=>{try{const r=await api("/api/ai/manager/telegram/test",{method:"POST"});const d=await r.json();showState(r.ok?(isEn?"Telegram test delivered.":"تم تسليم اختبار Telegram."):((isEn?"Telegram failed: ":"فشل Telegram: ")+(d.error||d.status)));}catch(e){showState(String(e.message||e))}};
const loadRepairs=async()=>{try{const r=await api("/api/ai/manager/repairs?limit=30");const d=await r.json();if(!r.ok)throw new Error(d.error||d.status);document.querySelector("#repairList").innerHTML=(d.jobs||[]).map(x=>'<article class="card"><b>#'+x.id+' · '+escapeHtml(x.status)+'</b><p>'+escapeHtml(x.context||"")+'</p><small>'+escapeHtml(x.error_text||"")+'</small><div class="actions">'+((x.status==="FAILED"||x.status==="WAITING")?'<button class="secondary repair-retry" data-id="'+x.id+'">'+(isEn?"Retry":"إعادة المحاولة")+'</button>':"")+'</div></article>').join("")||'<p class="muted">'+(isEn?"No repair jobs.":"لا توجد مهام إصلاح.")+'</p>';}catch(e){showState(String(e.message||e))}};
document.querySelector("#aiRepairSubmit").onclick=async()=>{const box=document.querySelector("#aiRepairRequest"),state=document.querySelector("#aiRepairState");const request=box?.value.trim()||"";if(request.length<10){if(state)state.textContent=isEn?"Please describe the requested change/problem.":"اكتب وصفًا واضحًا للمشكلة أو التعديل المطلوب.";return;}try{if(state)state.textContent=isEn?"Submitting to BAYAN AI…":"جارٍ إرسال الطلب إلى BAYAN AI…";const r=await api("/api/ai/manager/repair-request",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({request,mode:"fix"})});const d=await r.json();if(!r.ok)throw new Error(d.error||d.status);if(state)state.textContent=(isEn?"Request #":"الطلب رقم ")+d.id+" "+(isEn?"was queued for AI diagnosis and verification.":"تم وضعه في طابور التشخيص والإصلاح والتحقق.");box.value="";loadRepairs();}catch(e){if(state)state.textContent=String(e.message||e)}};document.querySelector("#aiRepairDiagnose").onclick=async()=>{const box=document.querySelector("#aiRepairRequest"),state=document.querySelector("#aiRepairState"),request=box?.value.trim()||"";if(request.length<10){if(state)state.textContent=isEn?"Please describe the issue first.":"اكتب المشكلة أولًا.";return;}try{if(state)state.textContent=isEn?"Submitting diagnosis request…":"جارٍ إرسال طلب التشخيص…";const r=await api("/api/ai/manager/repair-request",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({request,mode:"diagnose"})});const d=await r.json();if(!r.ok)throw new Error(d.error||d.status);if(state)state.textContent=(isEn?"Diagnosis request #":"طلب التشخيص رقم ")+d.id+" "+(isEn?"was queued.":"تم وضعه في الطابور.");}catch(e){if(state)state.textContent=String(e.message||e)}};document.querySelector("#repairsLoad").onclick=loadRepairs;
document.querySelector("#repairsRetryAll").onclick=async()=>{try{const r=await api("/api/ai/manager/repairs/retry-all",{method:"POST"});const d=await r.json();showState(r.ok?((isEn?"Queued ":"تم وضع ")+d.queued+(isEn?" repair jobs for retry.":" مهمة إصلاح لإعادة المحاولة.")):(d.error||d.status));loadRepairs();}catch(e){showState(String(e.message||e))}};
document.querySelector("#reviewLoad").onclick=async()=>{try{const r=await api("/api/contributions/review");const d=await r.json();if(!r.ok)throw new Error(d.error||d.status);document.querySelector("#reviewList").innerHTML=(d.items||[]).map(x=>'<article class="card"><b>#'+x.id+' · '+escapeHtml(x.status)+'</b><h3>'+escapeHtml(x.title)+'</h3><p>'+escapeHtml(x.body)+'</p>'+(x.source?'<p class="muted">'+escapeHtml(x.source)+'</p>':"")+'<div class="actions"><button class="secondary review-action" data-id="'+x.id+'" data-status="VERIFIED">'+(isEn?"Verify":"تحقق")+'</button><button class="secondary review-action" data-id="'+x.id+'" data-status="NEEDS_MORE_INFO">'+(isEn?"Need info":"تحتاج معلومات")+'</button><button class="secondary review-action" data-id="'+x.id+'" data-status="REJECTED">'+(isEn?"Reject":"رفض")+'</button></div></article>').join("")||'<p class="muted">'+(isEn?"No pending contributions.":"لا توجد مساهمات قيد المراجعة.")+'</p>';}catch(e){showState(String(e.message||e))}};
document.querySelector("#requestsLoad").onclick=async()=>{try{const r=await api("/api/requests/review");const d=await r.json();if(!r.ok)throw new Error(d.error||d.status);document.querySelector("#requestList").innerHTML=(d.items||[]).map(x=>'<article class="card"><b>#'+x.id+' · '+escapeHtml(x.status)+'</b><h3>'+escapeHtml(x.title)+'</h3><p>'+escapeHtml(x.body)+'</p><small>'+escapeHtml(x.request_type||"")+'</small><div class="actions"><button class="secondary request-action" data-id="'+x.id+'" data-status="IN_PROGRESS"> '+(isEn?"Start":"بدء")+'</button><button class="secondary request-action" data-id="'+x.id+'" data-status="RESOLVED">'+(isEn?"Resolve":"حل")+'</button><button class="secondary request-action" data-id="'+x.id+'" data-status="REJECTED">'+(isEn?"Reject":"رفض")+'</button></div></article>').join("")||'<p class="muted">'+(isEn?"No pending requests.":"لا توجد طلبات قيد المراجعة.")+'</p>';}catch(e){showState(String(e.message||e))}};
const loadAnalytics=async()=>{try{const r=await api("/api/analytics?hours=24");const d=await r.json();if(!r.ok)throw new Error(d.error||d.status);document.querySelector("#analyticsPanel").innerHTML='<article class="card"><h3>'+(isEn?"Private analytics — last 24h":"الإحصاءات الخاصة — آخر 24 ساعة")+'</h3><div class="grid"><div class="card"><b>'+(isEn?"Views":"المشاهدات")+'</b><strong>'+d.views+'</strong></div><div class="card"><b>'+(isEn?"Visitors":"الزوار")+'</b><strong>'+d.uniqueVisitors+'</strong></div><div class="card"><b>'+(isEn?"Searches":"البحث")+'</b><strong>'+d.searches+'</strong></div><div class="card"><b>'+(isEn?"Top pages":"أكثر الصفحات")+'</b><p>'+((d.topPages||[]).map(x=>escapeHtml(x.path)+" · "+x.count).join("<br>")||"—")+'</p></div></div></article>';}catch(e){document.querySelector("#analyticsPanel").innerHTML='<article class="card"><p class="muted">'+escapeHtml(String(e.message||e))+'</p></article>'}};
const loadManagerArticles=async()=>{
 try{
  const status=document.querySelector("#managerArticleStatus").value;
  const r=await api("/api/ai/manager/articles?limit=50"+(status?"&status="+encodeURIComponent(status):""));
  const d=await r.json();if(!r.ok)throw new Error(d.error||d.status);
  document.querySelector("#managerArticles").innerHTML=(d.articles||[]).map(x=>{
   const image=x.hero_image_url?'<img class="news-image" loading="lazy" src="'+escapeHtml(safeHref(x.hero_image_url,""))+'" alt="'+escapeHtml(x.hero_image_alt||x.title||"")+'">':'<div class="card"><p class="muted">'+(isEn?"No hero image":"لا توجد صورة رئيسية")+'</p></div>';
   return '<article class="card"><b>'+escapeHtml(x.status)+' · '+escapeHtml(x.section||"")+'</b><h3>'+escapeHtml(x.title||x.slug)+'</h3>'+image+'<p class="muted">'+escapeHtml(x.hero_image_status||"NONE")+' · '+escapeHtml(x.hero_image_credit||"—")+'</p><div class="actions">'+
    (x.status!=="PUBLISHED"?'<button class="secondary article-status" data-slug="'+escapeHtml(x.slug)+'" data-status="PUBLISHED">'+(isEn?"Publish":"نشر")+'</button>':"")+
    (x.status==="PUBLISHED"?'<button class="secondary article-status" data-slug="'+escapeHtml(x.slug)+'" data-status="DRAFT">'+(isEn?"Move to draft":"إرجاع لمسودة")+'</button>':"")+
    '<button class="secondary article-validate" data-slug="'+escapeHtml(x.slug)+'">'+(isEn?"Validate":"تحقق")+'</button><button class="secondary article-duplicate" data-slug="'+escapeHtml(x.slug)+'">'+(isEn?"Duplicate":"نسخ كمسودة")+'</button><button class="secondary article-edit" data-slug="'+escapeHtml(x.slug)+'">'+(isEn?"Edit article":"تعديل المقال")+'</button><button class="secondary article-auto-image" data-slug="'+escapeHtml(x.slug)+'">'+(isEn?"Auto image":"إصلاح الصورة تلقائيًا")+'</button>'+
    (x.hero_image_url?'<button class="secondary article-clear-image" data-slug="'+escapeHtml(x.slug)+'">'+(isEn?"Clear image":"إزالة الصورة")+'</button>':"")+
   '</div></article>';
  }).join("")||'<p class="muted">'+(isEn?"No articles found.":"لا توجد مقالات.")+'</p>';
 }catch(e){showState(String(e.message||e))}
};
const loadNewsDiagnostics=async()=>{
 try{
  const r=await api("/api/ai/manager/news-diagnostics?lang="+(isEn?"en":"ar"));const d=await r.json();if(!r.ok)throw new Error(d.error||d.status);
  document.querySelector("#newsHealthPanel").innerHTML='<article class="card"><b>'+(isEn?"News provider":"مزود الأخبار")+'</b><p>'+escapeHtml((d.sources||[]).join(" · ")||"—")+'</p></article><article class="card"><b>'+(isEn?"Articles":"المقالات")+'</b><p>'+d.articleCount+'</p></article><article class="card"><b>'+(isEn?"Image coverage":"تغطية الصور")+'</b><p>'+Math.round((d.imageCoverage||0)*100)+'% ('+d.imageCount+'/'+d.articleCount+')</p></article><article class="card"><b>'+(isEn?"Newest item":"أحدث خبر")+'</b><p>'+escapeHtml(d.newestAt||"—")+'</p></article>';
 }catch(e){document.querySelector("#newsHealthPanel").innerHTML='<p class="muted">'+escapeHtml(String(e.message||e))+'</p>'}
};
